<style>
.mcn-workspace{min-height:100vh;background:#f5f5f3;padding:1.25rem}.mcn-workspace .card{border:1px solid #e4e4e7!important;border-radius:1rem!important;box-shadow:0 1px 3px rgba(0,0,0,.05)!important;overflow:hidden}.mcn-workspace .card-header{background:#fff!important;border-bottom:1px solid #e4e4e7!important}.mcn-workspace .form-control,.mcn-workspace .custom-select,.mcn-workspace .form-select{min-height:42px;border:1px solid #d4d4d8!important;border-radius:.75rem!important;background:#fafafa!important;color:#18181b!important}.mcn-workspace .form-control:focus,.mcn-workspace .custom-select:focus,.mcn-workspace .form-select:focus{border-color:#18181b!important;box-shadow:0 0 0 3px rgba(24,24,27,.08)!important;background:#fff!important}.mcn-workspace .btn-primary,.mcn-workspace .btn-success,.mcn-workspace .btn-dark{border-color:#161616!important;background:#161616!important;color:#fff!important}.mcn-workspace table thead th{border-color:#27272a!important;background:#161616!important;color:#fff!important;font-size:10px!important;font-weight:700!important;letter-spacing:.08em;text-transform:uppercase;vertical-align:middle!important}.mcn-workspace table tbody td{border-color:#f0f0f0!important;color:#3f3f46!important;vertical-align:middle!important}.mcn-workspace table tbody tr:hover{background:#fafafa!important}.mcn-workspace .modal-content{border:0!important;border-radius:1.25rem!important;box-shadow:0 24px 60px rgba(0,0,0,.22)!important;overflow:hidden}.mcn-workspace .modal-header{border-bottom:1px solid #e4e4e7!important;background:#161616!important;color:#fff!important}.mcn-workspace .modal-footer{border-top:1px solid #e4e4e7!important;background:#fafafa!important}@media(min-width:640px){.mcn-workspace{padding:1.5rem}}
</style>
<style>
.native-table-pagination{display:flex;align-items:center;justify-content:space-between;gap:1rem;border-top:1px solid #e4e4e7;background:#fff;padding:1rem 1.25rem;color:#71717a;font-size:.78rem}.native-table-pagination__actions{display:flex;align-items:center;gap:.4rem}.native-table-pagination button{display:inline-flex;min-width:34px;height:34px;align-items:center;justify-content:center;border:1px solid #e4e4e7;border-radius:.65rem;background:#fff;color:#3f3f46;font-weight:700;transition:.2s}.native-table-pagination button:hover:not(:disabled),.native-table-pagination button.is-active{border-color:#161616;background:#161616;color:#fff}.native-table-pagination button:disabled{cursor:not-allowed;opacity:.35}@media(max-width:640px){.native-table-pagination{align-items:flex-start;flex-direction:column}}
.mcn-filter-panel{isolation:isolate}.mcn-filter-grid>div{min-width:0}.mcn-filter-grid label{line-height:1.25}.mcn-filter-grid select,.mcn-filter-grid input{min-height:44px}.mcn-filter-panel .choices{position:relative;z-index:40;width:100%;margin:0}.mcn-filter-panel .choices.is-open{z-index:10000}.mcn-filter-panel .choices__inner{display:flex;min-height:44px;align-items:center;border-radius:.75rem;background:#fff;padding:.45rem .75rem}.mcn-filter-panel .choices__list--single{padding:0}.mcn-filter-panel .choices__list--dropdown,.mcn-filter-panel .choices__list[aria-expanded]{z-index:10001;margin-top:.4rem;overflow:hidden;border:1px solid #d4d4d8;border-radius:.85rem;background:#fff;box-shadow:0 18px 45px rgba(24,24,27,.18)}.mcn-filter-panel .choices__list--dropdown .choices__list,.mcn-filter-panel .choices__list[aria-expanded] .choices__list{max-height:340px;overscroll-behavior:contain}.mcn-filter-panel .choices__input{position:sticky;top:0;z-index:2;margin:0;border-bottom:1px solid #e4e4e7;background:#fff;padding:.75rem}.mcn-filter-panel .choices__item--choice{padding:.7rem .85rem;font-size:.875rem}.mcn-filter-panel .choices__item--choice.is-highlighted{background:#f4f4f5;color:#18181b}
</style>
